// Package rulecatalog loads the generated OCR rule catalog and any project
// override at .opencodereview/rules/catalog.json.
//
// The embedded catalog is generated by scripts/build-rule-catalog.go. Rule IDs
// from it are the only values accepted for a finding's rule_id; a project
// catalog may add repository-specific IDs or override metadata.
package rulecatalog

import (
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
)

// Schema is the catalog schema this package understands.
const Schema = "ocr-rule-catalog/v1"

//go:embed catalog.json
var defaultCatalogJSON []byte

// Source describes an upstream repository and revision the catalog was built
// from.
type Source struct {
	Name    string `json:"name"`
	Repo    string `json:"repo,omitempty"`
	Commit  string `json:"commit"`
	License string `json:"license"`
	Path    string `json:"path"`
}

// RuleSource locates a rule in its upstream document.
type RuleSource struct {
	Repo string `json:"repo"`
	Path string `json:"path"`
	Line int    `json:"line"`
}

// AppliesTo narrows a rule to path globs or keywords.
type AppliesTo struct {
	Paths    []string `json:"paths,omitempty"`
	Keywords []string `json:"keywords,omitempty"`
}

// Rule is one catalog entry.
type Rule struct {
	ID             string     `json:"id"`
	Namespace      string     `json:"namespace"`
	Prefix         string     `json:"prefix"`
	Title          string     `json:"title"`
	Domain         string     `json:"domain"`
	Severity       string     `json:"severity"`
	SourceSeverity string     `json:"source_severity,omitempty"`
	Check          string     `json:"check"`
	AppliesTo      *AppliesTo `json:"applies_to,omitempty"`
	Source         RuleSource `json:"source"`
	Status         string     `json:"status"`
}

// Reference indexes a knowledge document. Reference IDs are not rule IDs.
type Reference struct {
	ID       string   `json:"id"`
	Module   string   `json:"module"`
	Domain   string   `json:"domain"`
	Facet    string   `json:"facet,omitempty"`
	Audience string   `json:"audience,omitempty"`
	Path     string   `json:"path"`
	Keywords []string `json:"keywords,omitempty"`
}

// Namespace documents one ID space in the catalog.
type Namespace struct {
	Description string            `json:"description"`
	Prefixes    map[string]string `json:"prefixes,omitempty"`
}

// Counts summarizes the catalog contents.
type Counts struct {
	Rules             int            `json:"rules"`
	CPF               int            `json:"cpf"`
	OCR               int            `json:"ocr"`
	References        int            `json:"references"`
	ReferenceCatalogs int            `json:"reference_catalogs"`
	ByPrefix          map[string]int `json:"by_prefix"`
}

// Catalog is the in-memory rule directory.
type Catalog struct {
	Schema      string               `json:"schema"`
	Version     string               `json:"version"`
	GeneratedBy string               `json:"generated_by"`
	ContentHash string               `json:"content_hash"`
	Sources     []Source             `json:"sources"`
	Namespaces  map[string]Namespace `json:"namespaces"`
	Counts      Counts               `json:"counts"`
	Rules       []Rule               `json:"rules"`
	References  []Reference          `json:"references,omitempty"`

	indexOnce *sync.Once
	byID      map[string]int
}

// LoadDefault parses the embedded catalog.
func LoadDefault() (*Catalog, error) {
	cat, err := parse(defaultCatalogJSON, true)
	if err != nil {
		return nil, fmt.Errorf("embedded rule catalog: %w", err)
	}
	return cat, nil
}

// Load parses the embedded catalog and overlays a project catalog when
// repoDir/.opencodereview/rules/catalog.json exists. A missing project catalog
// is not an error.
func Load(repoDir string) (*Catalog, error) {
	cat, err := LoadDefault()
	if err != nil {
		return nil, err
	}
	if repoDir == "" {
		return cat, nil
	}

	path := filepath.Join(repoDir, ".opencodereview", "rules", "catalog.json")
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return cat, nil
	}
	if err != nil {
		return nil, fmt.Errorf("read project rule catalog %s: %w", path, err)
	}
	project, err := parse(data, false)
	if err != nil {
		return nil, fmt.Errorf("project rule catalog %s: %w", path, err)
	}
	if err := cat.Merge(project); err != nil {
		return nil, fmt.Errorf("merge project rule catalog %s: %w", path, err)
	}
	return cat, nil
}

// Merge adds or replaces project rules and references.
func (c *Catalog) Merge(other *Catalog) error {
	if c == nil || other == nil {
		return nil
	}
	c.ensureIndex()
	other.ensureIndex()

	otherIDs := make([]string, 0, len(other.byID))
	for id := range other.byID {
		otherIDs = append(otherIDs, id)
	}
	sort.Strings(otherIDs)
	for _, id := range otherIDs {
		index := other.byID[id]
		if existing, ok := c.byID[id]; ok {
			c.Rules[existing] = mergeRule(c.Rules[existing], other.Rules[index])
			continue
		}
		c.Rules = append(c.Rules, other.Rules[index])
	}

	refIndex := make(map[string]int, len(c.References))
	for i, ref := range c.References {
		refIndex[ref.ID] = i
	}
	for _, ref := range other.References {
		if existing, ok := refIndex[ref.ID]; ok {
			c.References[existing] = ref
			continue
		}
		refIndex[ref.ID] = len(c.References)
		c.References = append(c.References, ref)
	}

	for _, source := range other.Sources {
		duplicate := false
		for _, existing := range c.Sources {
			if existing.Name == source.Name {
				duplicate = true
				break
			}
		}
		if !duplicate {
			c.Sources = append(c.Sources, source)
		}
	}
	if len(other.Namespaces) > 0 && c.Namespaces == nil {
		c.Namespaces = make(map[string]Namespace, len(other.Namespaces))
	}
	for name, namespace := range other.Namespaces {
		c.Namespaces[name] = namespace
	}

	c.resetIndex()
	c.recount()
	// A merged catalog no longer matches the generated artifact hash.
	c.ContentHash = ""
	return nil
}

// mergeRule overlays non-empty project fields on an embedded rule so a partial
// override does not erase metadata the project did not restate.
func mergeRule(base, override Rule) Rule {
	if override.Namespace != "" {
		base.Namespace = override.Namespace
	}
	if override.Prefix != "" {
		base.Prefix = override.Prefix
	}
	if override.Title != "" {
		base.Title = override.Title
	}
	if override.Domain != "" {
		base.Domain = override.Domain
	}
	if override.Severity != "" {
		base.Severity = override.Severity
	}
	if override.SourceSeverity != "" {
		base.SourceSeverity = override.SourceSeverity
	}
	if override.Check != "" {
		base.Check = override.Check
	}
	base.Source.Path = override.Source.Path
	base.Source.Line = override.Source.Line
	if override.Source.Repo != "" {
		base.Source.Repo = override.Source.Repo
	}
	if override.AppliesTo != nil && (len(override.AppliesTo.Paths) > 0 || len(override.AppliesTo.Keywords) > 0) {
		base.AppliesTo = override.AppliesTo
	}
	if override.Status != "" {
		base.Status = override.Status
	}
	return base
}

// HasRule reports whether every comma-separated ID exists in the catalog.
func (c *Catalog) HasRule(id string) bool {
	if c == nil {
		return false
	}
	c.ensureIndex()
	for _, part := range strings.Split(id, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			return false
		}
		if _, ok := c.byID[part]; !ok {
			return false
		}
	}
	return true
}

// RuleIDs returns every catalog ID in sorted order.
func (c *Catalog) RuleIDs() []string {
	if c == nil {
		return nil
	}
	c.ensureIndex()
	ids := make([]string, 0, len(c.byID))
	for id := range c.byID {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

// Len returns the number of rules in the catalog.
func (c *Catalog) Len() int {
	if c == nil {
		return 0
	}
	return len(c.Rules)
}

func parse(data []byte, strict bool) (*Catalog, error) {
	var cat Catalog
	if err := json.Unmarshal(data, &cat); err != nil {
		return nil, err
	}
	if err := cat.validate(strict); err != nil {
		return nil, err
	}
	cat.resetIndex()
	return &cat, nil
}

func (c *Catalog) validate(strict bool) error {
	if c.Schema != Schema {
		return fmt.Errorf("catalog schema = %q, want %q", c.Schema, Schema)
	}
	if len(c.Rules) == 0 {
		return errors.New("catalog has no rules")
	}
	if strict && c.Version == "" {
		return errors.New("catalog version is empty")
	}

	seen := make(map[string]struct{}, len(c.Rules))
	for _, rule := range c.Rules {
		if strings.TrimSpace(rule.ID) == "" {
			return errors.New("catalog rule with empty id")
		}
		if _, duplicate := seen[rule.ID]; duplicate {
			return fmt.Errorf("duplicate rule ID %q", rule.ID)
		}
		seen[rule.ID] = struct{}{}
		if rule.Source.Path == "" || rule.Source.Line <= 0 {
			return fmt.Errorf("rule %s has no source location", rule.ID)
		}
		if strict {
			if rule.Prefix == "" {
				return fmt.Errorf("rule %s has empty prefix", rule.ID)
			}
			if rule.Domain == "" {
				return fmt.Errorf("rule %s has empty domain", rule.ID)
			}
			if rule.Severity == "" {
				return fmt.Errorf("rule %s has empty severity", rule.ID)
			}
			if strings.TrimSpace(rule.Check) == "" {
				return fmt.Errorf("rule %s has empty check", rule.ID)
			}
			if rule.Namespace == "" {
				return fmt.Errorf("rule %s has empty namespace", rule.ID)
			}
		}
	}

	refSeen := make(map[string]struct{}, len(c.References))
	for _, ref := range c.References {
		if ref.ID == "" || ref.Path == "" {
			return fmt.Errorf("reference with empty id or path: %+v", ref)
		}
		if _, duplicate := refSeen[ref.ID]; duplicate {
			return fmt.Errorf("duplicate reference ID %q", ref.ID)
		}
		refSeen[ref.ID] = struct{}{}
	}
	return nil
}

func (c *Catalog) ensureIndex() {
	if c.indexOnce == nil {
		c.indexOnce = &sync.Once{}
	}
	c.indexOnce.Do(func() {
		c.byID = make(map[string]int, len(c.Rules))
		for i, rule := range c.Rules {
			c.byID[rule.ID] = i
		}
	})
}

func (c *Catalog) resetIndex() {
	c.indexOnce = &sync.Once{}
	c.byID = nil
}

func (c *Catalog) recount() {
	counts := Counts{
		Rules:             len(c.Rules),
		References:        len(c.References),
		ReferenceCatalogs: c.Counts.ReferenceCatalogs,
		ByPrefix:          make(map[string]int, len(c.Rules)),
	}
	for _, rule := range c.Rules {
		counts.ByPrefix[rule.Prefix]++
		switch rule.Namespace {
		case "cpf":
			counts.CPF++
		case "ocr":
			counts.OCR++
		}
	}
	c.Counts = counts
}
